{
  "name": "Expediente Médico Pro",
  "description": "Sistema de gestión de expedientes médicos optimizado para claridad, velocidad y simplicidad, diseñado para profesionales de la salud."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Gender {
  MASCULINO = 'Masculino',
  FEMENINO = 'Femenino',
  OTRO = 'Otro'
}

export interface Visit {
  id: string;
  patientId: string;
  date: string; // ISO String
  notes: string;
  treatment: string;
  medications: string;
  createdAt: string;
}

export interface Patient {
  id: string;
  name: string;
  gender: Gender;
  age: number;
  dui: string;
  medicalHistory: string;
  createdAt: string;
}

export interface User {
  id: string;
  email: string;
  name: string;
}

export interface AppState {
  user: User | null;
  patients: Patient[];
  visits: Visit[];
}

import { Patient, Visit, User, AppState, Gender } from './types';

const STORAGE_KEY = 'medical_records_data_v1';

const INITIAL_STATE: AppState = {
  user: null,
  patients: [],
  visits: [],
};

export const db = {
  get: (): AppState => {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : INITIAL_STATE;
  },
  save: (state: AppState) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  },
  reset: () => {
    localStorage.removeItem(STORAGE_KEY);
  }
};

// Seed initial user if not exists
const checkSeed = () => {
  const state = db.get();
  // For demo, we don't seed the active user, just ensure we have a structure.
  db.save(state);
};
checkSeed();

import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route, Navigate, Link, useNavigate, useParams } from 'react-router-dom';
import { db } from './store';
import { AppState, User, Patient, Visit, Gender } from './types';

// Pages
import LoginPage from './pages/LoginPage';
import Dashboard from './pages/Dashboard';
import NewPatient from './pages/NewPatient';
import PatientDetail from './pages/PatientDetail';

// Layout Component
const Layout: React.FC<{ children: React.ReactNode, user: User | null, onLogout: () => void }> = ({ children, user, onLogout }) => {
  if (!user) return <>{children}</>;

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10 shadow-sm">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 h-16 flex items-center justify-between">
          <Link to="/" className="flex items-center space-x-2 group">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-bold group-hover:bg-blue-700 transition-colors">
              +
            </div>
            <span className="font-bold text-slate-800 text-lg tracking-tight">ExpedienteMédico</span>
          </Link>
          <div className="flex items-center space-x-6">
            <div className="hidden sm:block text-right">
              <p className="text-sm font-medium text-slate-900">Dr. {user.name}</p>
              <p className="text-xs text-slate-500">Sesión activa</p>
            </div>
            <button 
              onClick={onLogout}
              className="text-sm font-semibold text-red-600 hover:text-red-700 transition-colors px-3 py-1 border border-red-100 hover:border-red-200 rounded-md bg-red-50"
            >
              Cerrar sesión
            </button>
          </div>
        </div>
      </header>
      <main className="flex-1 max-w-6xl mx-auto w-full px-4 sm:px-6 py-8">
        {children}
      </main>
      <footer className="bg-white border-t border-slate-200 py-6 mt-auto">
        <div className="max-w-6xl mx-auto px-4 text-center text-slate-400 text-sm">
          &copy; {new Date().getFullYear()} Expediente Médico Pro. Sistema Confidencial.
        </div>
      </footer>
    </div>
  );
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(db.get());

  useEffect(() => {
    db.save(state);
  }, [state]);

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, user }));
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, user: null }));
  };

  const addPatient = (patient: Omit<Patient, 'id' | 'createdAt'>) => {
    const newPatient: Patient = {
      ...patient,
      id: crypto.randomUUID(),
      createdAt: new Date().toISOString()
    };
    setState(prev => ({
      ...prev,
      patients: [...prev.patients, newPatient]
    }));
    return newPatient.id;
  };

  const addVisit = (visit: Omit<Visit, 'id' | 'date' | 'createdAt'>) => {
    const newVisit: Visit = {
      ...visit,
      id: crypto.randomUUID(),
      date: new Date().toISOString(),
      createdAt: new Date().toISOString()
    };
    setState(prev => ({
      ...prev,
      visits: [...prev.visits, newVisit]
    }));
  };

  const isDuiUnique = (dui: string) => {
    return !state.patients.some(p => p.dui === dui);
  };

  return (
    <HashRouter>
      <Layout user={state.user} onLogout={handleLogout}>
        <Routes>
          <Route 
            path="/login" 
            element={state.user ? <Navigate to="/" /> : <LoginPage onLogin={handleLogin} />} 
          />
          <Route 
            path="/" 
            element={state.user ? <Dashboard patients={state.patients} visits={state.visits} /> : <Navigate to="/login" />} 
          />
          <Route 
            path="/patients/new" 
            element={state.user ? <NewPatient addPatient={addPatient} isDuiUnique={isDuiUnique} /> : <Navigate to="/login" />} 
          />
          <Route 
            path="/patients/:id" 
            element={state.user ? <PatientDetail patients={state.patients} visits={state.visits} addVisit={addVisit} /> : <Navigate to="/login" />} 
          />
          <Route path="*" element={<Navigate to="/" />} />
        </Routes>
      </Layout>
    </HashRouter>
  );
};

export default App;

