export default LoginPage;

import React, { useState, useMemo } from 'react';
import { Link } from 'react-router-dom';
import { Patient, Visit } from '../types';

interface DashboardProps {
  patients: Patient[];
  visits: Visit[];
}

const Dashboard: React.FC<DashboardProps> = ({ patients, visits }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [searchMode, setSearchMode] = useState<'name' | 'dui'>('name');

  const filteredPatients = useMemo(() => {
    if (!searchTerm) return [];

    const term = searchTerm.toLowerCase();
    return patients.filter(p => {
      if (searchMode === 'name') {
        return p.name.toLowerCase().includes(term);
      } else {
        return p.dui.includes(searchTerm);
      }
    });
  }, [patients, searchTerm, searchMode]);

  const getLastVisit = (patientId: string) => {
    const patientVisits = visits
      .filter(v => v.patientId === patientId)
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    return patientVisits[0] || null;
  };

  return (
    <div className="space-y-8 animate-fadeIn">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-extrabold text-slate-900">Buscador de Pacientes</h1>
          <p className="text-slate-500 text-lg">Localice expedientes por nombre o número de DUI</p>
        </div>
        <Link 
          to="/patients/new"
          className="inline-flex items-center px-6 py-3 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-700 transition-all shadow-lg shadow-blue-100 active:scale-95 text-lg"
        >
          <span className="mr-2 text-xl">+</span> Nuevo Paciente
        </Link>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <input
              type="text"
              placeholder={searchMode === 'name' ? 'Ej: Juan Pérez...' : 'Ej: 00000000-0'}
              className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-xl"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>
          </div>
          <div className="flex bg-slate-50 p-1 rounded-xl border border-slate-200">
            <button
              onClick={() => setSearchMode('name')}
              className={`px-6 py-3 rounded-lg font-semibold transition-all ${searchMode === 'name' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              Nombre
            </button>
            <button
              onClick={() => setSearchMode('dui')}
              className={`px-6 py-3 rounded-lg font-semibold transition-all ${searchMode === 'dui' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              DUI
            </button>
          </div>
        </div>
      </div>

      <div className="space-y-4">
        {searchTerm && filteredPatients.length > 0 ? (
          <div className="grid grid-cols-1 gap-4">
            {filteredPatients.map(patient => {
              const lastVisit = getLastVisit(patient.id);
              return (
                <Link 
                  key={patient.id} 
                  to={`/patients/${patient.id}`}
                  className="block bg-white border border-slate-200 p-6 rounded-2xl hover:border-blue-400 hover:shadow-md transition-all group"
                >
                  <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div className="space-y-1">
                      <div className="flex items-center space-x-3">
                        <h3 className="text-2xl font-bold text-slate-800 group-hover:text-blue-600 transition-colors">
                          {patient.name}
                        </h3>
                        <span className="px-2 py-1 bg-slate-100 text-slate-600 text-xs font-bold rounded uppercase">
                          {patient.dui}
                        </span>
                      </div>
                      <p className="text-slate-500 font-medium">
                        {patient.gender} • {patient.age} años
                      </p>
                    </div>

                    <div className="flex-1 md:max-w-md bg-slate-50 rounded-xl p-4 border border-slate-100">
                      <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Última Consulta</h4>
                      {lastVisit ? (
                        <div className="space-y-2">
                          <div>
                            <span className="text-xs font-bold text-blue-600">Tratamiento:</span>
                            <p className="text-sm text-slate-700 line-clamp-1">{lastVisit.treatment}</p>
                          </div>
                          <div>
                            <span className="text-xs font-bold text-blue-600">Medicamentos:</span>
                            <p className="text-sm text-slate-700 line-clamp-1">{lastVisit.medications}</p>
                          </div>
                        </div>
                      ) : (
                        <p className="text-sm italic text-slate-400">Sin consultas previas</p>
                      )}
                    </div>

                    <div className="hidden md:block">
                      <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center group-hover:bg-blue-600 group-hover:text-white transition-all">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                        </svg>
                      </div>
                    </div>
                  </div>
                </Link>
              );
            })}
          </div>
        ) : searchTerm ? (
          <div className="text-center py-20 bg-white rounded-2xl border-2 border-dashed border-slate-200">
            <p className="text-slate-400 text-lg">No se encontraron pacientes que coincidan con la búsqueda.</p>
          </div>
        ) : (
          <div className="text-center py-20 opacity-50">
            <div className="mx-auto w-24 h-24 bg-slate-100 rounded-full flex items-center justify-center mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
              </svg>
            </div>
            <p className="text-slate-400 text-lg font-medium italic">Escriba un nombre o DUI para comenzar</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { Gender } from '../types';

interface NewPatientProps {
  addPatient: (patient: any) => string;
  isDuiUnique: (dui: string) => boolean;
}

const NewPatient: React.FC<NewPatientProps> = ({ addPatient, isDuiUnique }) => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    name: '',
    dui: '',
    age: '',
    gender: Gender.MASCULINO,
    medicalHistory: ''
  });
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!formData.name.trim()) return setError('El nombre es requerido');
    if (!formData.dui.trim()) return setError('El DUI es requerido');
    if (!isDuiUnique(formData.dui)) return setError('Este DUI ya existe en el sistema');
    if (Number(formData.age) <= 0) return setError('La edad debe ser un número válido');

    const id = addPatient({
      ...formData,
      age: Number(formData.age)
    });

    navigate(`/patients/${id}`);
  };

  return (
    <div className="max-w-3xl mx-auto animate-fadeIn">
      <div className="mb-8 flex items-center justify-between">
        <div>
          <Link to="/" className="text-blue-600 font-semibold hover:underline flex items-center mb-2">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
            Regresar
          </Link>
          <h1 className="text-3xl font-extrabold text-slate-900">Nuevo Paciente</h1>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="p-8 space-y-6">
          {error && (
            <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded-md">
              <p className="text-sm text-red-700 font-bold">{error}</p>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="md:col-span-2">
              <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">
                Nombre Completo
              </label>
              <input
                type="text"
                required
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                placeholder="Nombre completo del paciente"
                value={formData.name}
                onChange={(e) => setFormData({...formData, name: e.target.value})}
              />
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">
                DUI
              </label>
              <input
                type="text"
                required
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                placeholder="00000000-0"
                value={formData.dui}
                onChange={(e) => setFormData({...formData, dui: e.target.value})}
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">
                  Edad
                </label>
                <input
                  type="number"
                  required
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                  placeholder="0"
                  value={formData.age}
                  onChange={(e) => setFormData({...formData, age: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">
                  Género
                </label>
                <select
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                  value={formData.gender}
                  onChange={(e) => setFormData({...formData, gender: e.target.value as Gender})}
                >
                  <option value={Gender.MASCULINO}>Masculino</option>
                  <option value={Gender.FEMENINO}>Femenino</option>
                  <option value={Gender.OTRO}>Otro</option>
                </select>
              </div>
            </div>

            <div className="md:col-span-2">
              <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">
                Antecedentes Médicos (Opcional)
              </label>
              <textarea
                rows={4}
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                placeholder="Escriba condiciones previas relevantes, alergias, cirugías..."
                value={formData.medicalHistory}
                onChange={(e) => setFormData({...formData, medicalHistory: e.target.value})}
              ></textarea>
            </div>
          </div>
        </div>

        <div className="bg-slate-50 p-6 flex items-center justify-end space-x-4 border-t border-slate-200">
          <Link 
            to="/" 
            className="px-6 py-3 text-slate-600 font-bold hover:text-slate-800 transition-colors"
          >
            Cancelar
          </Link>
          <button
            type="submit"
            className="px-8 py-3 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-700 transition-all shadow-lg shadow-blue-100 active:scale-95 text-lg"
          >
            Crear Expediente
          </button>
        </div>
      </form>
    </div>
  );
};

export default NewPatient;

import React, { useState, useMemo } from 'react';
import { useParams, Link } from 'react-router-dom';
import { Patient, Visit } from '../types';

interface PatientDetailProps {
  patients: Patient[];
  visits: Visit[];
  addVisit: (visit: any) => void;
}

const PatientDetail: React.FC<PatientDetailProps> = ({ patients, visits, addVisit }) => {
  const { id } = useParams<{ id: string }>();
  const [isNewVisitOpen, setIsNewVisitOpen] = useState(false);
  const [visitForm, setVisitForm] = useState({
    notes: '',
    treatment: '',
    medications: ''
  });

  const patient = useMemo(() => patients.find(p => p.id === id), [patients, id]);

  const patientVisits = useMemo(() => {
    return visits
      .filter(v => v.patientId === id)
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [visits, id]);

  if (!patient) {
    return (
      <div className="text-center py-20">
        <h2 className="text-2xl font-bold text-slate-800">Paciente no encontrado</h2>
        <Link to="/" className="text-blue-600 mt-4 inline-block hover:underline font-semibold">Volver al buscador</Link>
      </div>
    );
  }

  const handleSaveVisit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!visitForm.notes.trim() && !visitForm.treatment.trim()) return;

    addVisit({
      patientId: patient.id,
      ...visitForm
    });

    setVisitForm({ notes: '', treatment: '', medications: '' });
    setIsNewVisitOpen(false);
  };

