import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { Gender } from '../types';

interface NewPatientProps {
  addPatientWithFirstVisit: (patient: any, visit: any) => string;
  isDuiUnique: (dui: string) => boolean;
}

const NewPatient: React.FC<NewPatientProps> = ({ addPatientWithFirstVisit, isDuiUnique }) => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    name: '',
    dui: '',
    age: '',
    gender: Gender.MASCULINO,
    medicalHistory: ''
  });

  const [visitNotes, setVisitNotes] = useState<string[]>(['']);
  const [visitTreatment, setVisitTreatment] = useState('');
  const [visitMedications, setVisitMedications] = useState('');

  const [error, setError] = useState('');

  const handleNoteChange = (index: number, value: string) => {
    const newNotes = [...visitNotes];
    newNotes[index] = value;
    setVisitNotes(newNotes);
  };

  const handleNoteKeyDown = (index: number, e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      const newNotes = [...visitNotes];
      newNotes.splice(index + 1, 0, '');
      setVisitNotes(newNotes);
      setTimeout(() => {
        const nextInput = document.getElementById(`note-input-${index + 1}`);
        nextInput?.focus();
      }, 0);
    } else if (e.key === 'Backspace' && visitNotes[index] === '' && visitNotes.length > 1) {
      e.preventDefault();
      const newNotes = [...visitNotes];
      newNotes.splice(index, 1);
      setVisitNotes(newNotes);
      setTimeout(() => {
        const prevInput = document.getElementById(`note-input-${index - 1}`);
        prevInput?.focus();
      }, 0);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!formData.name.trim()) return setError('El nombre es requerido');
    if (!formData.dui.trim()) return setError('El DUI es requerido');
    if (!isDuiUnique(formData.dui)) return setError('Este DUI ya existe en el sistema');
    if (Number(formData.age) <= 0) return setError('La edad debe ser un número válido');

    const cleanNotes = visitNotes.filter(n => n.trim() !== '');
    if (cleanNotes.length === 0) return setError('Debe ingresar al menos un punto en la consulta');

    const id = addPatientWithFirstVisit(
      {
        ...formData,
        age: Number(formData.age)
      },
      {
        notes: cleanNotes,
        treatment: visitTreatment,
        medications: visitMedications
      }
    );

    navigate(`/patients/${id}`);
  };

  return (
    <div className="max-w-4xl mx-auto animate-fadeIn pb-12">
      <div className="mb-8 flex items-center justify-between">
        <div>
          <Link to="/" className="text-blue-600 font-semibold hover:underline flex items-center mb-2">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
            Regresar
          </Link>
          <h1 className="text-3xl font-extrabold text-slate-900">Crear Expediente Inicial</h1>
          <p className="text-slate-500">Información del paciente y primera consulta</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">
        {error && (
          <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded-xl">
            <p className="text-sm text-red-700 font-bold">{error}</p>
          </div>
        )}

        {/* Section 1: Personal Info */}
        <section className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="bg-slate-50 px-8 py-4 border-b border-slate-200">
            <h2 className="text-lg font-bold text-slate-800 flex items-center uppercase tracking-wider">
              <span className="w-8 h-8 bg-blue-600 text-white rounded-full flex items-center justify-center mr-3 text-sm">1</span>
              Datos Personales y Antecedentes
            </h2>
          </div>
          <div className="p-8 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="md:col-span-2">
                <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">Nombre Completo</label>
                <input
                  type="text"
                  required
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                  placeholder="Nombre completo del paciente"
                  value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                />
              </div>

              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">DUI</label>
                <input
                  type="text"
                  required
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                  placeholder="00000000-0"
                  value={formData.dui}
                  onChange={(e) => setFormData({...formData, dui: e.target.value})}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">Edad</label>
                  <input
                    type="number"
                    required
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                    placeholder="0"
                    value={formData.age}
                    onChange={(e) => setFormData({...formData, age: e.target.value})}
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">Género</label>
                  <select
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                    value={formData.gender}
                    onChange={(e) => setFormData({...formData, gender: e.target.value as Gender})}
                  >
                    <option value={Gender.MASCULINO}>Masculino</option>
                    <option value={Gender.FEMENINO}>Femenino</option>
                    <option value={Gender.OTRO}>Otro</option>
                  </select>
                </div>
              </div>

              <div className="md:col-span-2">
                <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">Antecedentes Médicos</label>
                <textarea
                  rows={3}
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                  placeholder="Escriba condiciones previas, alergias relevantes..."
                  value={formData.medicalHistory}
                  onChange={(e) => setFormData({...formData, medicalHistory: e.target.value})}
                ></textarea>
              </div>
            </div>
          </div>
        </section>

        {/* Section 2: First Visit */}
        <section className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="bg-slate-50 px-8 py-4 border-b border-slate-200">
            <h2 className="text-lg font-bold text-slate-800 flex items-center uppercase tracking-wider">
              <span className="w-8 h-8 bg-blue-600 text-white rounded-full flex items-center justify-center mr-3 text-sm">2</span>
              Motivo de Primera Consulta
            </h2>
          </div>
          <div className="p-8 space-y-6">
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-3 uppercase tracking-wide">Puntos Clave de la Consulta <span className="text-slate-400 font-normal lowercase">(Presione ENTER para nueva línea)</span></label>
              <div className="space-y-3">
                {visitNotes.map((note, index) => (
                  <div key={index} className="flex items-center space-x-3 group">
                    <span className="flex-shrink-0 w-6 h-6 flex items-center justify-center bg-blue-100 text-blue-600 rounded-full text-xs font-bold">{index + 1}</span>
                    <input
                      id={`note-input-${index}`}
                      type="text"
                      autoFocus={index === visitNotes.length - 1 && index > 0}
                      className="flex-1 px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                      placeholder="Escriba un punto..."
                      value={note}
                      onChange={(e) => handleNoteChange(index, e.target.value)}
                      onKeyDown={(e) => handleNoteKeyDown(index, e)}
                    />
                  </div>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-4">
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">Tratamiento inicial</label>
                <textarea 
                  rows={3}
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                  placeholder="Recomendaciones..."
                  value={visitTreatment}
                  onChange={(e) => setVisitTreatment(e.target.value)}
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">Medicamentos iniciales</label>
                <textarea 
                  rows={3}
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                  placeholder="Receta..."
                  value={visitMedications}
                  onChange={(e) => setVisitMedications(e.target.value)}
                />
              </div>
            </div>
          </div>
        </section>

        <div className="flex items-center justify-end space-x-6">
          <Link to="/" className="text-slate-600 font-bold hover:text-slate-800 transition-colors">Cancelar</Link>
          <button
            type="submit"
            className="px-12 py-4 bg-blue-600 text-white font-black rounded-2xl hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 active:scale-95 text-xl"
          >
            Guardar Expediente Completo
          </button>
        </div>
      </form>
    </div>
  );
};

export default NewPatient;

import React, { useState, useMemo } from 'react';
import { useParams, Link } from 'react-router-dom';
import { Patient, Visit } from '../types';

interface PatientDetailProps {
  patients: Patient[];
  visits: Visit[];
  addVisit: (visit: any) => void;
  doctorName: string;
}

const PatientDetail: React.FC<PatientDetailProps> = ({ patients, visits, addVisit, doctorName }) => {
  const { id } = useParams<{ id: string }>();
  const [isNewVisitOpen, setIsNewVisitOpen] = useState(false);
  const [visitNotes, setVisitNotes] = useState<string[]>(['']);
  const [visitTreatment, setVisitTreatment] = useState('');
  const [visitMedications, setVisitMedications] = useState('');

  const patient = useMemo(() => patients.find(p => p.id === id), [patients, id]);

  const patientVisits = useMemo(() => {
    return visits
      .filter(v => v.patientId === id)
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [visits, id]);

  if (!patient) {
    return (
      <div className="text-center py-20">
        <h2 className="text-2xl font-bold text-slate-800">Paciente no encontrado</h2>
        <Link to="/" className="text-blue-600 mt-4 inline-block hover:underline font-semibold">Volver al buscador</Link>
      </div>
    );
  }

  const handleNoteChange = (index: number, value: string) => {
    const newNotes = [...visitNotes];
    newNotes[index] = value;
    setVisitNotes(newNotes);
  };

  const handleNoteKeyDown = (index: number, e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      const newNotes = [...visitNotes];
      newNotes.splice(index + 1, 0, '');
      setVisitNotes(newNotes);
      setTimeout(() => {
        const nextInput = document.getElementById(`note-input-${index + 1}`);
        nextInput?.focus();
      }, 0);
    } else if (e.key === 'Backspace' && visitNotes[index] === '' && visitNotes.length > 1) {
      e.preventDefault();
      const newNotes = [...visitNotes];
      newNotes.splice(index, 1);
      setVisitNotes(newNotes);
      setTimeout(() => {
        const prevInput = document.getElementById(`note-input-${index - 1}`);
        prevInput?.focus();
      }, 0);
    }
  };

  const handleSaveVisit = (e: React.FormEvent) => {
    e.preventDefault();
    const cleanNotes = visitNotes.filter(n => n.trim() !== '');
    if (cleanNotes.length === 0 && !visitTreatment.trim()) return;

    addVisit({
      patientId: patient.id,
      notes: cleanNotes,
      treatment: visitTreatment,
      medications: visitMedications
    });

    setVisitNotes(['']);
    setVisitTreatment('');
    setVisitMedications('');
    setIsNewVisitOpen(false);
  };

  const formatDate = (isoString: string) => {
    return new Intl.DateTimeFormat('es-SV', {
      year: 'numeric', month: 'long', day: 'numeric',
      hour: '2-digit', minute: '2-digit'
    }).format(new Date(isoString));
  };

  const handlePrint = (visit: Visit) => {
    // Hidden content specifically for printing
    const printContent = `
      <div style="font-family: 'Inter', sans-serif; padding: 40px; color: #1e293b; max-width: 800px; margin: 0 auto;">
        <div style="border-bottom: 3px solid #2563eb; padding-bottom: 20px; margin-bottom: 30px; display: flex; justify-content: space-between; align-items: flex-end;">
          <div>
            <h1 style="margin: 0; font-size: 28px; color: #1e293b;">Dr. ${doctorName}</h1>
            <p style="margin: 5px 0 0; color: #64748b; font-weight: 600;">CONSULTA MÉDICA PROFESIONAL</p>
          </div>
          <div style="text-align: right;">
            <p style="margin: 0; font-size: 14px; font-weight: bold;">FECHA: ${new Date(visit.date).toLocaleDateString('es-SV')}</p>
          </div>
        </div>

        <div style="background: #f8fafc; padding: 20px; border-radius: 12px; margin-bottom: 30px;">
          <p style="margin: 0; font-size: 18px;"><strong>PACIENTE:</strong> ${patient.name}</p>
          <p style="margin: 5px 0 0; font-size: 14px; color: #64748b;">DUI: ${patient.dui} | Edad: ${patient.age} años | Género: ${patient.gender}</p>
        </div>

        <div style="margin-bottom: 40px;">
          <h2 style="font-size: 16px; text-transform: uppercase; letter-spacing: 1px; color: #2563eb; border-bottom: 1px solid #e2e8f0; padding-bottom: 10px; margin-bottom: 20px;">Receta Médica / Indicaciones</h2>
          <div style="font-size: 18px; line-height: 1.6; white-space: pre-wrap;">${visit.medications || "No se recetaron medicamentos."}</div>
        </div>

        <div style="margin-bottom: 40px;">
          <h2 style="font-size: 16px; text-transform: uppercase; letter-spacing: 1px; color: #2563eb; border-bottom: 1px solid #e2e8f0; padding-bottom: 10px; margin-bottom: 20px;">Recomendaciones / Tratamiento</h2>
          <div style="font-size: 16px; line-height: 1.6; white-space: pre-wrap;">${visit.treatment || "No se indicaron recomendaciones adicionales."}</div>
        </div>

        <div style="margin-top: 100px; text-align: center;">
          <div style="width: 250px; border-top: 1px solid #1e293b; margin: 0 auto 10px;"></div>
          <p style="margin: 0; font-weight: bold;">Firma y Sello Médico</p>
        </div>

        <div style="position: fixed; bottom: 20px; left: 0; right: 0; text-align: center; font-size: 10px; color: #cbd5e1;">
          Documento generado por Expediente Médico Pro - ${new Date().toLocaleString()}
        </div>
      </div>
    `;

    const printWindow = window.open('', '_blank');
    if (printWindow) {
      printWindow.document.write(`
        <html>
          <head>
            <title>Receta - ${patient.name}</title>
            <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap" rel="stylesheet">
            <style>body { margin: 0; }</style>
          </head>
          <body>${printContent}</body>
        </html>
      `);
      printWindow.document.close();
      printWindow.focus();
      setTimeout(() => {
        printWindow.print();
        printWindow.close();
      }, 500);
    }
  };

  return (
    <div className="space-y-8 animate-fadeIn pb-20 print:hidden">
      {/* Patient Header Card */}
      <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="bg-blue-600 px-8 py-6 text-white">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div>
              <div className="flex items-center space-x-2 text-blue-100 text-sm font-bold uppercase tracking-wider mb-2">
                <Link to="/" className="hover:text-white transition-colors">Pacientes</Link>
                <span>/</span>
                <span className="text-white">Expediente</span>
              </div>
              <h1 className="text-4xl font-black">{patient.name}</h1>
            </div>
            <div className="bg-blue-500 bg-opacity-30 px-4 py-2 rounded-xl backdrop-blur-sm border border-blue-400 border-opacity-30">
              <span className="block text-xs font-bold uppercase tracking-widest text-blue-100 opacity-70">Número de DUI</span>
              <span className="text-xl font-mono font-bold">{patient.dui}</span>
            </div>
          </div>
        </div>

        <div className="p-8 grid grid-cols-1 md:grid-cols-3 gap-8">
          <div className="space-y-1">
            <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Información Básica</span>
            <p className="text-xl text-slate-700">
              <span className="font-bold">{patient.age} años</span> • {patient.gender}
            </p>
          </div>
          <div className="md:col-span-2 space-y-1">
            <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Antecedentes Médicos</span>
            <p className="text-lg text-slate-700 leading-relaxed italic">
              {patient.medicalHistory || "Sin antecedentes registrados."}
            </p>
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-black text-slate-800 flex items-center">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 mr-2 text-blue-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
          </svg>
          Historial de Consultas
        </h2>
        {!isNewVisitOpen && (
          <button 
            onClick={() => setIsNewVisitOpen(true)}
            className="px-6 py-3 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-700 transition-all shadow-lg shadow-blue-100 flex items-center"
          >
            <span className="mr-2 text-xl">+</span> Nueva Consulta
          </button>
        )}
      </div>

      {/* New Visit Form Card */}
      {isNewVisitOpen && (
        <div className="bg-white rounded-2xl shadow-xl border-2 border-blue-400 overflow-hidden animate-slideUp">
          <div className="bg-blue-50 px-8 py-4 border-b border-blue-100 flex justify-between items-center">
            <h3 className="text-lg font-bold text-blue-800 uppercase">Nueva Hoja de Consulta</h3>
            <button 
              onClick={() => setIsNewVisitOpen(false)}
              className="text-slate-400 hover:text-slate-600 font-bold transition-colors"
            >
              Cerrar [×]
            </button>
          </div>
          <form onSubmit={handleSaveVisit} className="p-8 space-y-6">
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-3 uppercase tracking-wide">Puntos Clave de la Consulta <span className="text-slate-400 font-normal lowercase">(Enter para nueva línea)</span></label>
              <div className="space-y-3">
                {visitNotes.map((note, index) => (
                  <div key={index} className="flex items-center space-x-3">
                    <span className="flex-shrink-0 w-6 h-6 flex items-center justify-center bg-blue-100 text-blue-600 rounded-full text-xs font-bold">{index + 1}</span>
                    <input
                      id={`note-input-${index}`}
                      type="text"
                      className="flex-1 px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                      placeholder="Ingrese observación..."
                      value={note}
                      onChange={(e) => handleNoteChange(index, e.target.value)}
                      onKeyDown={(e) => handleNoteKeyDown(index, e)}
                    />
                  </div>
                ))}
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-4">
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">Tratamiento / Recomendaciones</label>
                <textarea 
                  rows={3}
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                  placeholder="Instrucciones..."
                  value={visitTreatment}
                  onChange={(e) => setVisitTreatment(e.target.value)}
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide">Medicamentos Recetados</label>
                <textarea 
                  rows={3}
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all text-lg"
                  placeholder="Dosis y fármacos..."
                  value={visitMedications}
                  onChange={(e) => setVisitMedications(e.target.value)}
                />
              </div>
            </div>
            <div className="flex justify-end pt-4">
              <button 
                type="submit"
                className="px-10 py-4 bg-green-600 text-white font-black rounded-xl hover:bg-green-700 transition-all shadow-lg shadow-green-100 text-lg"
              >
                Guardar Consulta
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Visits History Timeline */}
      <div className="space-y-6">
        {patientVisits.length > 0 ? (
          patientVisits.map((visit, index) => (
            <div key={visit.id} className="relative bg-white border border-slate-200 rounded-2xl p-8 shadow-sm group hover:border-blue-200 transition-all">
              {index === 0 && (
                <div className="absolute -left-3 top-8 bg-blue-600 text-white text-[10px] font-black uppercase px-2 py-1 rounded shadow-sm rotate-[-90deg]">
                  Actual
                </div>
              )}

              <div className="flex flex-col md:flex-row gap-8">
                <div className="md:w-1/4">
                  <span className="text-xs font-black text-blue-600 uppercase tracking-widest block mb-1">Fecha</span>
                  <p className="text-lg font-bold text-slate-800">{formatDate(visit.date)}</p>

                  <button 
                    onClick={() => handlePrint(visit)}
                    className="mt-6 flex items-center text-sm font-bold text-slate-600 hover:text-blue-600 border border-slate-200 px-4 py-2 rounded-lg bg-slate-50 hover:bg-blue-50 transition-all"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" />
                    </svg>
                    Imprimir Receta
                  </button>
                </div>

                <div className="flex-1 space-y-6">
                  <div>
                    <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-3">Puntos de Consulta</h4>
                    <ul className="space-y-2">
                      {visit.notes.map((note, i) => (
                        <li key={i} className="flex items-start">
                          <span className="w-1.5 h-1.5 bg-blue-400 rounded-full mt-2.5 mr-3 flex-shrink-0"></span>
                          <span className="text-lg text-slate-700 leading-relaxed">{note}</span>
                        </li>
                      ))}
                    </ul>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-50 p-6 rounded-2xl border border-slate-100">
                    <div>
                      <h4 className="text-xs font-black text-blue-500 uppercase tracking-widest mb-2">Tratamiento</h4>
                      <p className="text-slate-700 font-medium whitespace-pre-wrap">{visit.treatment || "No especificado."}</p>
                    </div>
                    <div>
                      <h4 className="text-xs font-black text-blue-500 uppercase tracking-widest mb-2">Medicamentos</h4>
                      <p className="text-slate-700 font-medium whitespace-pre-wrap">{visit.medications || "No especificado."}</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ))
        ) : (
          <div className="bg-white border-2 border-dashed border-slate-200 rounded-3xl p-16 text-center">
            <p className="text-slate-400 text-xl font-bold italic">No hay historial de consultas registrado.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default PatientDetail;

export enum Gender {
  MASCULINO = 'Masculino',
  FEMENINO = 'Femenino',
  OTRO = 'Otro'
}

export interface Visit {
  id: string;
  patientId: string;
  date: string; // ISO String
  notes: string[];
  treatment: string;
  medications: string;
  createdAt: string;
}

export interface Patient {
  id: string;
  name: string;
  gender: Gender;
  age: number;
  dui?: string; // Optional
  address: string; // New field
  medicalHistory: string;
  createdAt: string;
}

export interface User {
  id: string;
  email: string;
  name: string;
}

export interface AppState {
  user: User | null;
  patients: Patient[];
  visits: Visit[];
}

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate, Link } from 'react-router-dom';
import { db } from './store';
import { AppState, User, Patient, Visit } from './types';

// Pages
import LoginPage from './pages/LoginPage';
import Dashboard from './pages/Dashboard';
import NewPatient from './pages/NewPatient';
import PatientDetail from './pages/PatientDetail';

const Layout: React.FC<{ children: React.ReactNode, user: User | null, onLogout: () => void }> = ({ children, user, onLogout }) => {
  if (!user) return <>{children}</>;

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 print:bg-white">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10 shadow-sm print:hidden">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 h-16 flex items-center justify-between">
          <Link to="/" className="flex items-center space-x-2 group">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-bold group-hover:bg-blue-700 transition-colors">
              +
            </div>
            <span className="font-bold text-slate-800 text-lg tracking-tight">ExpedienteMédico</span>
          </Link>
          <div className="flex items-center space-x-6">
            <div className="hidden sm:block text-right">
              <p className="text-sm font-medium text-slate-900">Dr. {user.name}</p>
              <p className="text-xs text-slate-500">Sesión activa</p>
            </div>
            <button 
              onClick={onLogout}
              className="text-sm font-semibold text-red-600 hover:text-red-700 transition-colors px-3 py-1 border border-red-100 hover:border-red-200 rounded-md bg-red-50"
            >
              Cerrar sesión
            </button>
          </div>
        </div>
      </header>
      <main className="flex-1 max-w-6xl mx-auto w-full px-4 sm:px-6 py-8 print:p-0 print:max-w-none">
        {children}
      </main>
      <footer className="bg-white border-t border-slate-200 py-6 mt-auto print:hidden">
        <div className="max-w-6xl mx-auto px-4 text-center text-slate-400 text-sm">
          &copy; {new Date().getFullYear()} Expediente Médico Pro. Sistema Confidencial.
        </div>
      </footer>
    </div>
  );
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(db.get());

  useEffect(() => {
    db.save(state);
  }, [state]);

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, user }));
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, user: null }));
  };

  const addPatientWithFirstVisit = (patientData: Omit<Patient, 'id' | 'createdAt'>, visitData: Omit<Visit, 'id' | 'patientId' | 'date' | 'createdAt'>) => {
    const patientId = crypto.randomUUID();
    const now = new Date().toISOString();

    const newPatient: Patient = {
      ...patientData,
      id: patientId,
      createdAt: now
    };

    const firstVisit: Visit = {
      ...visitData,
      id: crypto.randomUUID(),
      patientId: patientId,
      date: now,
      createdAt: now
    };

    setState(prev => ({
      ...prev,
      patients: [...prev.patients, newPatient],
      visits: [...prev.visits, firstVisit]
    }));

    return patientId;
  };

  const addVisit = (visit: Omit<Visit, 'id' | 'date' | 'createdAt'>) => {
    const newVisit: Visit = {
      ...visit,
      id: crypto.randomUUID(),
      date: new Date().toISOString(),
      createdAt: new Date().toISOString()
    };
    setState(prev => ({
      ...prev,
      visits: [...prev.visits, newVisit]
    }));
  };

  const isDuiUnique = (dui: string) => {
    if (!dui.trim()) return true; // If empty, it's "unique" enough (allowed)
    return !state.patients.some(p => p.dui === dui);
  };

  return (
    <HashRouter>
      <Layout user={state.user} onLogout={handleLogout}>
        <Routes>
          <Route 
            path="/login" 
            element={state.user ? <Navigate to="/" /> : <LoginPage onLogin={handleLogin} />} 
          />
          <Route 
            path="/" 
            element={state.user ? <Dashboard patients={state.patients} visits={state.visits} /> : <Navigate to="/login" />} 
          />
          <Route 
            path="/patients/new" 
            element={state.user ? <NewPatient addPatientWithFirstVisit={addPatientWithFirstVisit} isDuiUnique={isDuiUnique} /> : <Navigate to="/login" />} 
          />
          <Route 
            path="/patients/:id" 
            element={state.user ? <PatientDetail patients={state.patients} visits={state.visits} addVisit={addVisit} doctorName={state.user?.name || ''} /> : <Navigate to="/login" />} 
          />
          <Route path="*" element={<Navigate to="/" />} />
        </Routes>
      </Layout>
    </HashRouter>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Link } from 'react-router-dom';
import { Patient, Visit } from '../types';

interface DashboardProps {
  patients: Patient[];
  visits: Visit[];
}

const Dashboard: React.FC<DashboardProps> = ({ patients, visits }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [searchMode, setSearchMode] = useState<'name' | 'dui'>('name');

  const filteredPatients = useMemo(() => {
    if (!searchTerm) return [];

    const term = searchTerm.toLowerCase();
    return patients.filter(p => {
      if (searchMode === 'name') {
        return p.name.toLowerCase().includes(term);
      } else {
        return p.dui?.includes(searchTerm);
      }
    });
  }, [patients, searchTerm, searchMode]);

  const recentPatients = useMemo(() => {
    return [...patients]
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
      .slice(0, 5);
  }, [patients]);

  const getLastVisit = (patientId: string) => {
    const patientVisits = visits
      .filter(v => v.patientId === patientId)
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    return patientVisits[0] || null;
  };

  const formatDateShort = (isoString: string) => {
    return new Intl.DateTimeFormat('es-SV', {
      day: '2-digit', month: '2-digit', year: 'numeric'
    }).format(new Date(isoString));
  };

  const PatientCard = ({ patient }: { patient: Patient }) => {
    const lastVisit = getLastVisit(patient.id);
    return (
      <Link 
        to={`/patients/${patient.id}`}
        className="block bg-white border border-slate-200 p-6 rounded-2xl hover:border-blue-400 hover:shadow-md transition-all group"
      >
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="space-y-1 flex-1">
            <div className="flex items-center space-x-3">
              <h3 className="text-2xl font-bold text-slate-800 group-hover:text-blue-600 transition-colors">
                {patient.name}
              </h3>
              {patient.dui && (
                <span className="px-2 py-1 bg-slate-100 text-slate-600 text-xs font-bold rounded uppercase">
                  {patient.dui}
