              )}
            </div>
            <div className="flex flex-col space-y-1 text-slate-500 font-medium">
              <p>{patient.gender} • {patient.age} años</p>
              <p className="text-sm flex items-center italic">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
                </svg>
                {patient.address || "Sin dirección"}
              </p>
            </div>
          </div>

          <div className="flex-1 md:max-w-md bg-slate-50 rounded-xl p-4 border border-slate-100">
            <div className="flex justify-between items-start mb-2">
              <h4 className="text-xs font-black text-slate-400 uppercase tracking-wider">Última Consulta</h4>
              {lastVisit && (
                <span className="text-[10px] font-bold text-blue-600 bg-blue-50 px-2 py-0.5 rounded border border-blue-100">
                  {formatDateShort(lastVisit.date)}
