            </button>
            <button
              onClick={() => setSearchMode('dui')}
              className={`px-6 py-3 rounded-lg font-semibold transition-all ${searchMode === 'dui' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              DUI
            </button>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        {searchTerm ? (
          <div>
            <h2 className="text-xl font-bold text-slate-800 mb-4 flex items-center">
              Resultados de Búsqueda
              <span className="ml-3 px-2 py-0.5 bg-slate-100 text-slate-500 text-sm rounded-full font-medium">
                {filteredPatients.length}
