                      </svg>
                      Imprimir
                    </button>
                  </div>
                </div>

                <div className="flex-1 space-y-8">
                  <div>
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Puntos Tratados</h4>
                    <ul className="space-y-4">
