                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8 bg-slate-50 p-8 rounded-[2rem] border border-slate-100 group-hover:bg-emerald-50/20 group-hover:border-emerald-100 transition-colors">
