            >
              Cancelar [×]
            </button>
          </div>

          <div className="flex flex-col lg:flex-row">
            {/* Left Column: Editor */}
            <form onSubmit={handleSaveVisit} className="flex-1 p-10 space-y-8 border-r border-slate-100">
